mapper.insert:
     INSERT INTO seinfo_work (
  user_email, title, content, work_date, created_at, mfile_group_id, hours, category, deleted
)
VALUES (
  #{userEmail}, #{title}, #{content}, #{workDate, jdbcType=TIMESTAMP}, NOW(), #{fileGrpId}, #{hours}, #{category}, #{deleted}
)

mapper.update:
UPDATE seinfo_work
SET deleted = 1, updated_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT w.id, w.user_email, w.title, w.content, w.work_date, w.created_at, w.updated_at, w.mfile_group_id, w.hours, w.category, w.deleted, w.approval_status, w.approved_by, w.approved_at, w.rejection_reason, CASE WHEN v.user_role = 'ADMIN' THEN '관리자' ELSE v.login_id END AS userNm FROM seinfo_work w LEFT JOIN seinfo_vendor_manager v ON w.user_email = v.user_email WHERE w.deleted = false
AND w.user_email = #{currentUserEmail}
ORDER BY w.work_date DESC
